// Differential checks of CaseHeuristics.js against Lean, generated by leanscript --check
import * as M from "./CaseHeuristics.js";

function show(v) {
  if (Array.isArray(v) || ArrayBuffer.isView(v)) return "#[" + [...v].map(show).join(", ") + "]";
  return String(v);
}
function floatBits(x) {
  return String(new BigUint64Array(new Float64Array([x]).buffer)[0]);
}
function isNaNBits(s) {
  const b = BigInt(s);
  return ((b >> 52n) & 0x7ffn) === 0x7ffn && (b & 0xfffffffffffffn) !== 0n;
}
let passed = 0, failed = 0;
function check(label, thunk, expected, isFloat) {
  let got;
  try {
    const v = thunk();
    got = isFloat ? floatBits(v) : show(v);
    // NaN payloads differ between platforms: any NaN matches any NaN
    if (isFloat && Number.isNaN(v) && isNaNBits(expected)) got = expected;
  } catch (e) {
    got = "threw: " + e.message;
  }
  if (got === expected) passed++;
  else {
    failed++;
    console.log(`FAIL ${label}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(got)}`);
  }
}

check("testP(-7n, -7n, -7n)", () => M.testP(-7n, -7n, -7n), "5", false);
check("testP(-7n, -1n, -1n)", () => M.testP(-7n, -1n, -1n), "5", false);
check("testP(-1n, -1n, -7n)", () => M.testP(-1n, -1n, -7n), "5", false);
check("testP(-7n, 0n, 0n)", () => M.testP(-7n, 0n, 0n), "5", false);
check("testP(-1n, 0n, -1n)", () => M.testP(-1n, 0n, -1n), "5", false);
check("testP(0n, 0n, -7n)", () => M.testP(0n, 0n, -7n), "5", false);
check("testP(-7n, 3n, 3n)", () => M.testP(-7n, 3n, 3n), "5", false);
check("testP(-1n, 3n, 0n)", () => M.testP(-1n, 3n, 0n), "5", false);
check("testP(0n, -7n, 12n)", () => M.testP(0n, -7n, 12n), "5", false);
check("testP(0n, 3n, -1n)", () => M.testP(0n, 3n, -1n), "5", false);
check("testP(3n, -7n, 3n)", () => M.testP(3n, -7n, 3n), "5", false);
check("testP(3n, 3n, -7n)", () => M.testP(3n, 3n, -7n), "5", false);
check("testP(12n, -7n, 0n)", () => M.testP(12n, -7n, 0n), "5", false);
check("testP(-7n, 12n, 12n)", () => M.testP(-7n, 12n, 12n), "5", false);
check("testP(-1n, 12n, 3n)", () => M.testP(-1n, 12n, 3n), "5", false);
check("testP(0n, 12n, 0n)", () => M.testP(0n, 12n, 0n), "5", false);
check("testP(3n, -1n, 12n)", () => M.testP(3n, -1n, 12n), "5", false);
check("testP(3n, 12n, -1n)", () => M.testP(3n, 12n, -1n), "5", false);
check("testP(12n, -1n, 3n)", () => M.testP(12n, -1n, 3n), "5", false);
check("testP(12n, 12n, -7n)", () => M.testP(12n, 12n, -7n), "5", false);
check("testP(12n, 0n, 12n)", () => M.testP(12n, 0n, 12n), "5", false);

console.log(`CaseHeuristics.js: ${passed} passed, ${failed} failed`);
if (failed > 0) process.exit(1);
